import pandas as pd
import matplotlib.pyplot as plt
import os
import numpy as np

# ---------------- CONFIG ----------------

# This MUST match the OUTPUT_DIR from your tracker.py script
TRACK_OUTPUT_DIR = '/Users/tanishq/Desktop/particle3'

# The CSV file generated by tracker.py
CSV_FILE_PATH = os.path.join(TRACK_OUTPUT_DIR, "detected_centroids.csv")

# The name of the final map image we will create
OUTPUT_MAP_FILE = os.path.join(TRACK_OUTPUT_DIR, "trajectory_map.png")

# ---------------- Main Plotting Function ----------------

def plot_trajectories(csv_path, output_path):
    print(f"Loading data from {csv_path}...")
    try:
        # Read the CSV data into a pandas DataFrame
        df = pd.read_csv(csv_path)
    except FileNotFoundError:
        print(f"Error: CSV file not found at {csv_path}")
        print("Please make sure you have run tracker.py first.")
        return
    except Exception as e:
        print(f"Error reading CSV: {e}")
        return

    if df.empty:
        print("Error: The CSV file is empty. No data to plot.")
        return

    # Get the total number of unique particle IDs
    particle_ids = df['ID'].unique()
    num_particles = len(particle_ids)
    print(f"Found {num_particles} unique particle IDs.")

    # Create a color map to give each particle a distinct color
    # 'tab20' is a good colormap for 20 distinct items
    colors = plt.get_cmap('tab20')(np.linspace(0, 1, num_particles))

    # Create the plot
    plt.figure(figsize=(12, 12), facecolor='white')
    ax = plt.gca()
    ax.set_facecolor('white') # Set background to white

    print("Plotting trajectories for each particle...")

    # Group the data by 'ID' and plot each particle's path
    for i, particle_id in enumerate(particle_ids):
        # Get all data for this specific particle
        particle_data = df[df['ID'] == particle_id]
        
        # Sort by frame to ensure the path is correct
        particle_data = particle_data.sort_values(by='Frame')
        
        x_coords = particle_data['X']
        y_coords = particle_data['Y']
        
        if not x_coords.empty and not y_coords.empty:
            # Plot the trajectory line
            ax.plot(x_coords, y_coords, color=colors[i], label=f'ID {particle_id}')
            
            # Add the ID label at the *end* of the path
            ax.text(x_coords.iloc[-1], y_coords.iloc[-1], f' {particle_id}', color=colors[i], fontsize=9)

    # --- Styling the Plot ---
    
    # Invert the Y-axis to match image coordinates (0,0 at top-left)
    ax.invert_yaxis()
    
    # Set titles and labels
    ax.set_title(f'Particle Trajectory Map (Total {num_particles} Particles)', fontsize=16)
    ax.set_xlabel('X Coordinate', fontsize=12)
    ax.set_ylabel('Y Coordinate', fontsize=12)
    
    # Set equal aspect ratio so the circle isn't distorted
    ax.set_aspect('equal', adjustable='box')
    
    ax.grid(True, linestyle='--', alpha=0.6)
    
    # Hide the legend if there are too many particles
    if num_particles > 20:
        print("Note: More than 20 particles, hiding legend to avoid clutter.")
    else:
        # ax.legend(bbox_to_anchor=(1.05, 1), loc='upper left')
        pass # We are labeling lines directly, so a legend is not needed.

    # Save the final image
    plt.savefig(output_path, dpi=300, bbox_inches='tight')
    print(f"\n✅ Success! Trajectory map saved to: {output_path}")
    plt.close()

if __name__ == "__main__":
    plot_trajectories(CSV_FILE_PATH, OUTPUT_MAP_FILE)

    
